function createAvatarSvg(initials, role, bgCol1, bgCol2) {
  const svg = <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100" width="100" height="100">
    <defs>
      <linearGradient id="avGrad_ + initials + " x1="0%" y1="0%" x2="100%" y2="100%">
        <stop offset="0%" stop-color=" + (bgCol1 || '#059669') + "/>
        <stop offset="100%" stop-color=" + (bgCol2 || '#10b981') + "/>
      </linearGradient>
    </defs>
    <circle cx="50" cy="50" r="48" fill="url(#avGrad_ + initials + )" stroke="#ffffff" stroke-width="2"/>
    <text x="50" y="62" font-family="'Outfit', Arial, sans-serif" font-size="32" font-weight="bold" fill="#ffffff" text-anchor="middle"> + initials + </text>
  </svg>;
  return 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg);
}

